async function api(url,data){try{if(data&&!navigator.onLine)throw Error('Tidak terhubung ke server. Sambungkan internet atau Wi-Fi sebelum menyimpan transaksi.');const r=await fetch('/api/'+url,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const b=await r.json();if(!r.ok){if(r.status===401&&url!=='login')login();throw Error(b.error)}if(data)modal.querySelectorAll('form[data-guide-state="saving"]').forEach(form=>updateFormGuide(form,'saved'));return b}catch(error){modal.querySelectorAll('form[data-guide-state="saving"]').forEach(form=>updateFormGuide(form,'error'));throw error}}

let toastTimer;
function closeModal(){pdfRequestVersion++;activePdfPreview?.destroy();activePdfPreview=null;modal.close();placeToast()}
function placeToast(){const notice=$('#toast');if(notice)(modal.open?modal:document.body).append(notice);}
function toast(message){
 clearTimeout(toastTimer);let notice=$('#toast');if(!notice){notice=document.createElement('div');notice.id='toast';notice.setAttribute('role','status');document.body.append(notice)}
 const error=/gagal|tidak valid|tidak dapat|tidak bisa|belum berhasil|ditolak|berubah|muat ulang/i.test(message),success=!error&&/berhasil|tersimpan|diposting|siap|dimuat/i.test(message);
 notice.className=error?'toast-error':success?'toast-success':'toast-info';notice.setAttribute('aria-live','polite');notice.setAttribute('aria-atomic','true');
 notice.innerHTML='<div class="toast-icon">'+icon(error?'alert':success?'check':'bell')+'</div><div class="toast-content"><strong class="toast-title">'+(error?'Perlu diperhatikan':success?'Berhasil':'Notifikasi')+'</strong><p class="toast-message">'+esc(message)+'</p></div><button type="button" class="toast-close" aria-label="Tutup notifikasi" title="Tutup notifikasi">'+icon('close')+'</button>';
 notice.style.display='grid';placeToast();const dismiss=()=>{clearTimeout(toastTimer);notice.style.display='none'},schedule=()=>{clearTimeout(toastTimer);toastTimer=setTimeout(dismiss,error?12000:8000)};
 notice.querySelector('.toast-close').onclick=dismiss;notice.onmouseenter=()=>clearTimeout(toastTimer);notice.onmouseleave=schedule;notice.onfocusin=()=>clearTimeout(toastTimer);notice.onfocusout=schedule;schedule();
}

async function load(){try{state=await api('state');render();counterFromHash()}catch(e){if(!state)login();else toast(e.message)}}
const privileged=()=>['Super Admin','Finance','Akuntan'].includes(state.user.role);
const can=(...roles)=>roles.includes(state.user.role);
function statusTone(status){
 if(['Tidak Hadir','Terlambat','Hari Ini','Stok rendah','Belum dibayar','Belum lunas','Tidak Setuju','Tidak Jadi','Ditolak'].includes(status))return 'urgent';
 if(['7 Hari Mendatang','Terjadwal','DP','Baru','Menunggu','Menunggu Persetujuan','Menunggu Sparepart','Di Negosiasi','Diajukan','Di Bengkel','Terbuka'].includes(status))return 'attention';
 if(['Direncanakan','Sudah Dihubungi','Diagnosis','Siap Dikerjakan','Dikerjakan','QC'].includes(status))return 'progress';
 if(status==='Siap Keluar')return 'ready';
 if(['Dikonfirmasi','Sudah Masuk','Selesai','Lunas','Deal Pekerjaan','Estimasi Disetujui','Disetujui','Aktif','Keluar'].includes(status))return 'success';
 return 'neutral';
}
const statusLabel=status=>status==='Menunggu Persetujuan'?'Menunggu Persetujuan Pelanggan':status;
function badge(status){return '<span class="badge status-'+statusTone(status)+'"><i class="dot" style="background:currentColor;width:4px;height:4px"></i>'+esc(statusLabel(status))+'</span>'}

