function sidebarNavigation(){
 const available=allowedNav();
 const groups=[['Operasional',['mobileActions','dashboard','vehicles','estimates','orders','completedOrders','inventory']],['CRM',['vehicleFrequency','arrivalPlans','crmReminders']],['Master Data',['masterDashboard','vehicleMaster','suppliers','racks','serviceCatalog']],['Akuntansi',['accountingDashboard','finance','accounting','reports']],['Administrasi',['users','audit']]];
 return groups.map(([label,ids])=>{
 const entries=ids.map(id=>available.find(entry=>entry[0]===id)).filter(Boolean);if(!entries.length)return '';
 return '<div class="nav-group" role="group" aria-label="'+esc(label)+'"><div class="nav-label">'+esc(label)+'</div>'+entries.map(([id,i,name])=>'<button data-page="'+id+'" class="'+(page===id?'active':'')+'" title="'+esc(name)+'" aria-label="'+esc(name)+'" '+(page===id?'aria-current="page"':'')+'>'+icon(i)+'<span class="nav-text">'+esc(name)+'</span></button>').join('')+'</div>';
 }).join('');
}
