function mobileActionPage(){const actions=mobileActionsFor(state.user),active=state.visits.filter(v=>!v.exited&&!['Selesai','Tidak Jadi'].includes(v.progress));return '<section class="mobile-welcome"><div><div class="eyebrow">26 MOTOR PREMIUM</div><h1>Aksi Bengkel</h1><p>'+esc(state.user.name)+' · '+esc(state.user.role)+'</p></div><span class="mobile-connection" role="status"></span></section><div class="mobile-overview"><button data-page="orders">'+icon('wrench')+'<span><strong>'+active.length+'</strong> pekerjaan aktif</span></button><button data-page="vehicles">'+icon('car')+'<span><strong>'+state.visits.filter(v=>!v.exited).length+'</strong> kendaraan di bengkel</span></button></div><section class="panel mobile-action-panel"><div class="panel-head"><div><h2>Pilih Aksi</h2><p>Jalankan proses sesuai tugas Anda.</p></div></div><div class="mobile-action-grid">'+actions.map(a=>'<button '+(a.action?'data-action="'+a.action+'"':'data-page="'+a.page+'"')+'><span class="mobile-action-icon">'+icon(a.icon)+'</span><span><strong>'+esc(a.label)+'</strong><small>'+esc(a.description)+'</small></span>'+icon('chevron')+'</button>').join('')+'</div></section><section class="panel"><div class="panel-head"><h2>Dashboard & Menu</h2></div>'+dashboardLinks(['dashboard','vehicleFrequency','arrivalPlans','crmReminders','masterDashboard','accountingDashboard','completedOrders','vehicleMaster','suppliers','racks','serviceCatalog','inventory','reports','users','audit'])+'</section><section class="notice"><strong>Aplikasi Android</strong><p>Pasang APK di HP Android, lalu isi alamat server bengkel yang dapat dijangkau dari HP.</p><a class="mobile-apk-link" href="/downloads/26motor-premium.apk" download>Unduh APK Android</a></section><p class="hint">Data dan transaksi memakai server bengkel yang sama. Aksi tersedia sesuai hak akses akun.</p>'}
