function dashboardLinks(ids){const available=allowedNav();return '<div class="quick-grid">'+ids.map(id=>available.find(n=>n[0]===id)).filter(Boolean).map(([id,i,label])=>'<button class="quick" data-page="'+id+'">'+icon(i)+esc(label)+'</button>').join('')+'</div>'}
