 root.querySelectorAll('[data-crm-view]').forEach(button=>button.onclick=()=>crmReminderDetail(Number(button.dataset.crmView)));
 root.querySelectorAll('[data-crm-due]').forEach(button=>button.onclick=()=>{crmDueFilter=button.dataset.crmDue;menuStatus['Reminder Service']='Semua';render()});
