function frequencyData(){return vehicleFrequency(state,{...frequencyPeriod,search:query})}
function frequencyTable(rows){return rows.length?'<div class="table-wrap"><table><thead><tr><th>PERINGKAT</th><th>NOMOR POLISI</th><th>KENDARAAN</th><th>PELANGGAN TERAKHIR</th><th>JUMLAH KUNJUNGAN</th><th>MASUK PERTAMA DALAM PERIODE</th><th>MASUK TERAKHIR DALAM PERIODE</th><th>AKSI</th></tr></thead><tbody>'+rows.map((r,index)=>'<tr'+excelRecord({'Peringkat':index+1,'Nomor Polisi':r.plate,'Kendaraan':r.unit,'Pelanggan Terakhir':r.customer,'Jumlah Kunjungan':r.count,'Masuk Pertama Dalam Periode':dt(r.first),'Masuk Terakhir Dalam Periode':dt(r.last)})+'><td>'+String(index+1)+'</td><td><strong>'+esc(r.plate)+'</strong></td><td>'+esc(r.unit)+'</td><td>'+esc(r.customer)+'</td><td><button class="small" data-frequency-history="'+esc(r.key)+'" aria-label="Lihat '+r.count+' kunjungan '+esc(r.plate)+'">'+r.count+' kunjungan</button></td><td>'+dt(r.first)+'</td><td>'+dt(r.last)+'</td><td><button class="small" data-frequency-history="'+esc(r.key)+'">Riwayat Kunjungan</button></td></tr>').join('')+'</tbody></table></div>':empty('Belum ada kendaraan yang sesuai','Ubah periode atau pencarian. Kunjungan dihitung dari pendataan kendaraan masuk.','car')}
function vehicleFrequencyPage(){
 const data=frequencyData(),top=data.rows.slice(0,5),max=data.top?.count||1;
 const card=(key,label,value,note)=>'<button class="frequency-stat" data-frequency-summary="'+key+'"><span>'+label+'</span><strong>'+esc(value)+'</strong><small>'+esc(note)+'</small><span class="frequency-card-link">Lihat rincian →</span></button>';
 return title('ANALISIS KUNJUNGAN','Dashboard Kunjungan Kendaraan','Ketahui kendaraan yang paling sering ke bengkel dan telusuri riwayatnya.')+'<section class="panel"><form id="frequency-period" class="frequency-filters"><label>Dari tanggal<input type="date" name="from" aria-label="Dari tanggal" value="'+esc(frequencyPeriod.from)+'"></label><label>Sampai tanggal<input type="date" name="to" aria-label="Sampai tanggal" value="'+esc(frequencyPeriod.to)+'"></label><button class="primary" type="submit">Terapkan Periode</button><button type="button" data-frequency-preset="month">Bulan Ini</button><button type="button" data-frequency-preset="year">Tahun Ini</button><button type="button" data-frequency-preset="all">Semua Waktu</button></form><div class="filters"><input id="list-search" aria-label="Cari rekap kendaraan" placeholder="Cari nomor polisi, kendaraan, atau pelanggan…" value="'+esc(query)+'"></div></section><p class="hint frequency-period-note">Periode: '+(frequencyPeriod.from?esc(frequencyPeriod.from):'Awal pencatatan')+' sampai '+(frequencyPeriod.to?esc(frequencyPeriod.to):'data terbaru')+' · Berdasarkan tanggal masuk (WIB).'+(query?' Pencarian diterapkan ke seluruh ringkasan.':'')+'</p><div class="frequency-stats">'+card('visits','Total Kunjungan',data.totalVisits,'Pendataan kendaraan masuk dalam periode')+card('vehicles','Kendaraan Unik',data.uniqueVehicles,'Kendaraan dengan sedikitnya satu kunjungan')+card('repeat','Kendaraan Berulang',data.repeatVehicles,'Minimal dua kunjungan dalam periode')+card('top','Paling Sering',data.top?.plate||'Belum ada',data.top?data.top.count+' kunjungan dalam periode':'Belum ada kunjungan')+'</div><section class="panel"><div class="panel-head"><div><h2>5 Kendaraan Paling Sering</h2><p>Diurutkan dari kunjungan terbanyak; jika sama, kunjungan terbaru didahulukan.</p></div></div>'+(top.length?'<div class="frequency-chart">'+top.map((r,index)=>'<button class="frequency-bar" data-frequency-history="'+esc(r.key)+'"><span class="frequency-bar-label"><strong>'+String(index+1)+'. '+esc(r.plate)+'</strong><small>'+esc(r.customer)+'</small></span><span class="frequency-track"><span style="width:'+Math.round(r.count/max*100)+'%"></span></span><strong>'+r.count+' <small>kunjungan</small></strong></button>').join('')+'</div>':empty('Belum ada kunjungan pada periode ini','Catat kendaraan masuk atau pilih periode yang lain.','car'))+'</section><section class="panel"><div class="panel-head"><div><h2>Rekapitulasi Kunjungan Kendaraan</h2><p>'+data.uniqueVehicles+' kendaraan · '+data.totalVisits+' kunjungan. Ekspor Excel tersedia per tabel dan per baris.</p></div></div>'+frequencyTable(data.rows)+'</section><p class="notice">Satu pendataan kendaraan masuk dihitung sebagai satu kunjungan, termasuk pekerjaan yang masih berjalan atau sudah selesai. Kendaraan dan tipe master nonaktif tidak dihitung. '+(can('Teknisi')?'Data terbatas pada kunjungan yang ditugaskan kepada akun Anda.':'')+'</p>';
}
function bindVehicleFrequency(root=document){
 const historyButtons=scope=>scope.querySelectorAll('[data-frequency-history]').forEach(button=>button.onclick=()=>{const row=frequencyData().rows.find(r=>r.key===button.dataset.frequencyHistory);if(!row)return;open('Riwayat Kunjungan — '+esc(row.plate),'<p class="notice">'+row.count+' kunjungan sesuai periode dan pencarian di dashboard.</p>'+vehicleTable(row.visits));modal.querySelectorAll('[data-detail]').forEach(el=>el.onclick=()=>detail(Number(el.dataset.detail)))});
 historyButtons(root);
 root.querySelectorAll('[data-frequency-summary]').forEach(button=>button.onclick=()=>{const data=frequencyData(),kind=button.dataset.frequencySummary;if(kind==='visits'){open('Rincian Total Kunjungan','<p class="notice">'+data.totalVisits+' pendataan kendaraan masuk dalam periode.</p>'+vehicleTable(data.rows.flatMap(r=>r.visits).sort((a,b)=>Date.parse(b.entered)-Date.parse(a.entered))));modal.querySelectorAll('[data-detail]').forEach(el=>el.onclick=()=>detail(Number(el.dataset.detail)));}else{const rows=kind==='repeat'?data.rows.filter(r=>r.count>=2):kind==='top'?data.rows.slice(0,1):data.rows;open(kind==='repeat'?'Kendaraan Berulang':kind==='top'?'Kendaraan Paling Sering':'Kendaraan Unik',frequencyTable(rows));historyButtons(modal)}});
 const period=root.querySelector('#frequency-period');if(period)period.onsubmit=event=>{event.preventDefault();const proposed=Object.fromEntries(new FormData(period));try{vehicleFrequency(state,proposed);frequencyPeriod=proposed;render()}catch(error){toast(error.message)}};
 root.querySelectorAll('[data-frequency-preset]').forEach(button=>button.onclick=()=>{const today=jakartaVisitDay(new Date().toISOString()),preset=button.dataset.frequencyPreset;frequencyPeriod=preset==='all'?{from:'',to:''}:{from:preset==='month'?today.slice(0,7)+'-01':today.slice(0,4)+'-01-01',to:today};render()});
}
function masterDashboard(){
 const cards=[['Kendaraan Terdaftar','Kendaraan pelanggan aktif','car'],['Tipe Kendaraan','Tipe kendaraan aktif','car'],['Total Kode Sparepart','Kode sparepart aktif','box']];
 if(!can('Teknisi'))cards.push(['Supplier Aktif','Supplier untuk pengadaan sparepart','users'],['Rak Aktif','Lokasi penyimpanan yang dapat dipilih','box']);
 if(can('Super Admin','Admin'))cards.push(['Total Jasa Katalog','Harga jasa aktif untuk estimasi','wrench']);
 return title('MASTER DATA','Dashboard Master Data','Ringkasan data aktif dan kelengkapan master bengkel.')+'<div class="stats">'+cards.map(([label,sub,i])=>stat(label,0,sub,i)).join('')+'</div><div class="report-grid"><section class="panel"><div class="panel-head"><div><h2>Kelola Master Data</h2><p>Buka master untuk menambah atau memperbarui data.</p></div></div>'+dashboardLinks(['vehicleMaster','suppliers','racks','serviceCatalog','inventory'])+'</section><section class="panel"><div class="panel-head"><div><h2>Perlu Dilengkapi</h2><p>Hanya data aktif yang diperiksa.</p></div></div><div class="dashboard-checks">'+(can('Teknisi')?'':'<div class="amount-row"><span>Alamat / kontak supplier belum lengkap</span>'+counterLink('Supplier Belum Lengkap',counterData(state,'Supplier Belum Lengkap').total)+'</div>')+'<div class="amount-row"><span>Kecocokan kendaraan sparepart belum dipetakan</span>'+counterLink('Sparepart Belum Dipetakan',counterData(state,'Sparepart Belum Dipetakan').total)+'</div><p class="hint">Gunakan filter Nonaktif di menu master untuk meninjau atau mengaktifkan kembali data.</p></div></section></div>';
}
function accountingDashboard(){
 const invoices=state.visits.filter(v=>v.invoice&&v.total>v.paid),journals=state.journals||[],entries=journals.flatMap(j=>JSON.parse(j.entries)),debit=entries.reduce((sum,e)=>sum+(e.debit||0),0),credit=entries.reduce((sum,e)=>sum+(e.credit||0),0);
 const cards=[['Penjualan Terposting','Total seluruh invoice terposting','file'],['Penerimaan Kas','Pembayaran pelanggan tercatat','wallet'],['Piutang Pelanggan','Sisa tagihan pelanggan','clock'],['Hutang Supplier','Sisa pembayaran penerimaan sparepart','box'],['Pengeluaran Operasional','Pengeluaran kas / bank tercatat','wallet'],['Invoice Aktif','Invoice yang belum lunas','file']];
 return title('AKUNTANSI & KEUANGAN','Dashboard Akuntansi','Ringkasan seluruh transaksi tercatat, piutang, hutang, dan jurnal.')+'<div class="stats">'+cards.map(([label,sub,i])=>stat(label,0,sub,i)).join('')+'</div><div class="report-grid"><section class="panel"><div class="panel-head"><div><h2>Invoice Belum Lunas</h2><p>'+invoices.length+' invoice · saldo '+rp(invoices.reduce((sum,v)=>sum+v.total-v.paid,0))+'</p></div><button data-page="finance">Lihat semua →</button></div>'+(invoices.length?'<div class="table-wrap"><table><thead><tr><th>INVOICE / PELANGGAN</th><th>SISA TAGIHAN</th><th>AKSI</th></tr></thead><tbody>'+invoices.slice(0,8).map(v=>'<tr'+excelRecord({'Nomor Invoice':num('INV',v.invoice),'Pelanggan':v.customer,'Nomor Polisi':v.plate,'Sisa Tagihan':rp(v.total-v.paid)})+'><td><strong>'+num('INV',v.invoice)+'</strong><small>'+esc(v.customer)+' · '+esc(v.plate)+'</small></td><td>'+rp(v.total-v.paid)+'</td><td><button class="small" data-detail="'+v.id+'">Detail</button></td></tr>').join('')+'</tbody></table></div><div class="table-foot">Menampilkan '+Math.min(invoices.length,8)+' dari '+invoices.length+' invoice belum lunas</div>':empty('Tidak ada invoice belum lunas','Tagihan pelanggan yang belum lunas akan tampil di sini.','check'))+'</section><section class="panel"><div class="panel-head"><h2>Akses Keuangan</h2></div>'+dashboardLinks(['finance','accounting','reports'])+'</section></div>'+(can('Super Admin','Akuntan')?'<section class="panel"><div class="panel-head"><div><h2>Kontrol Jurnal & Periode</h2><p>Periksa keseimbangan seluruh jurnal yang telah diposting.</p></div><button data-page="accounting">Jurnal & Periode →</button></div><div class="dashboard-checks"><div class="amount-row"><span>Jurnal terposting</span>'+counterLink('Jurnal Terposting',journals.length)+'</div><div class="amount-row"><span>Total debit</span><strong>'+rp(debit)+'</strong></div><div class="amount-row"><span>Total kredit</span><strong>'+rp(credit)+'</strong></div><div class="amount-row"><span>Selisih debit / kredit</span><strong>'+rp(debit-credit)+'</strong></div><div class="amount-row"><span>Periode terkunci</span>'+counterLink('Periode Terkunci',state.periods.filter(p=>p.closed).length)+'</div><p class="hint">Periode yang belum pernah ditutup masih terbuka.</p></div></section>':'');
}
function counterLink(label,value,cls='count'){return '<a class="'+cls+'" href="#counter='+encodeURIComponent(label)+'" data-counter="'+esc(label)+'" aria-label="Lihat rincian '+esc(label)+'">'+value+'</a>'}
function stat(label,value,sub,i,accent=false){const data=counterData(state,label);if(data)value=data.total===null?'Belum lengkap':data.unit==='rupiah'?rp(data.total):data.total;return `<div class="stat ${accent?'accent':''}"><a class="stat-link" href="#counter=${encodeURIComponent(label)}" data-counter="${esc(label)}" aria-label="Lihat rincian ${esc(label)}"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(i)}</span></div><strong>${value}</strong></a><small>${icon('clock').replace('<svg ','<svg style="width:11px;height:11px" ')}${sub}</small><span class="stat-hint" aria-hidden="true">Lihat rincian ${icon('arrow')}</span></div>`}
function showCounter(label){
 const data=counterData(state,label);if(!data)return;
 const format=(v,type)=>v===null||v===undefined?'—':type==='money'?rp(v):type==='date'?dt(v):esc(v);
 const hasDetail=data.rows.some(r=>r.visitId);
 const summary=data.total===null?'Belum lengkap':data.unit==='rupiah'?rp(data.total):data.total+' '+data.unit;
 open('Rincian '+label,`<div class="counter-summary"><div><div class="eyebrow">${esc(label)}</div><strong>${esc(summary)}</strong></div><span>${data.rows.length} data ditampilkan</span></div>${data.note?'<p class="hint">'+esc(data.note)+'</p>':''}${data.rows.length?'<div class="table-wrap counter-table"><table><thead><tr>'+data.columns.map(c=>'<th>'+esc(c.label)+'</th>').join('')+(hasDetail?'<th>AKSI</th>':'')+'</tr></thead><tbody>'+data.rows.map(r=>'<tr'+(r.exportFields?excelRecord(r.exportFields):'')+'>'+r.values.map((v,i)=>'<td>'+format(v,data.columns[i].format)+'</td>').join('')+(hasDetail?'<td>'+(r.visitId?'<button class="small" data-counter-detail="'+r.visitId+'">Detail</button>':'')+'</td>':'')+'</tr>').join('')+'</tbody></table></div>':empty('Belum ada data untuk '+esc(label),'Jumlah rincian sesuai dengan counter saat ini.')}<div class="form-actions"><button data-counter-close>Tutup rincian</button></div>`);
 modal.classList.add('counter-dialog');
 modal.querySelector('[data-counter-close]').onclick=()=>closeModal();
 modal.querySelectorAll('[data-counter-detail]').forEach(el=>el.onclick=()=>detail(Number(el.dataset.counterDetail)));
}
function counterFromHash(){if(state&&location.hash.startsWith('#estimate=')){showEstimate(Number(location.hash.slice(10)));return}if(state&&location.hash.startsWith('#model-parts=')){showModelParts(Number(location.hash.slice(13)));return}if(state&&location.hash.startsWith('#counter=')){try{showCounter(decodeURIComponent(location.hash.slice(9)))}catch{toast('Tautan rincian tidak valid')}}}

function body(){if(!dashboardAllowed(page,state.user.role))page='dashboard';return ({mobileActions:mobileActionPage,dashboard,vehicleFrequency:vehicleFrequencyPage,crmReminders:crmRemindersPage,arrivalPlans:arrivalPlansPage,masterDashboard,accountingDashboard,suppliers:()=>inventoryMasterPage('suppliers'),racks:()=>inventoryMasterPage('racks'),serviceCatalog:serviceCatalogPage,estimates:estimatePage,vehicleMaster:vehicleMasterPage,vehicles:vehiclePage,orders:orderPage,completedOrders:completedOrdersPage,inventory:inventoryPage,finance:financePage,accounting:accountingPage,reports:reportPage,users:userPage,audit:auditPage}[page]||dashboard)()}
function dashboard(){const vs=state.visits,active=vs.filter(v=>!v.exited),ready=vs.filter(v=>v.status==='Siap Keluar'),low=state.items.filter(i=>i.qty<i.minimum),paid=state.payments.reduce((a,p)=>a+p.amount,0);const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta'}).format(new Date());const entered=vs.filter(v=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta'}).format(new Date(v.entered))===today).length;
 const filter=statusView('Ringkasan',active,visitDisplayStatus,progressStatuses);
 return title('OPERASIONAL BENGKEL','Dashboard Operasional','Pantau kendaraan, persetujuan pelanggan, dan progres pekerjaan.',can('Super Admin','Finance')?btn('Kendaraan Masuk','new-visit',true):'')+`<div class="stats">${stat('Kendaraan di Bengkel',active.length,`${counterLink('Kendaraan Masuk Hari Ini',entered+' kendaraan','stat-sub-link')} masuk hari ini`,'car')}${stat('Work Order Aktif',active.filter(v=>!['Selesai','Tidak Jadi'].includes(v.progress)).length,'Pekerjaan dalam antrean & proses','wrench')}${stat('Siap Keluar',ready.length,'Menunggu penyelesaian & serah terima','check')}${stat('Siap Dikerjakan',active.filter(v=>v.progress==='Siap Dikerjakan').length,'Estimasi telah disetujui pelanggan','check',true)}</div><div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h2>Kendaraan di Bengkel ${counterLink('Kendaraan di Bengkel',active.length)}</h2><p>Pantau kendaraan dan progres pengerjaan terkini.</p></div><button data-page="orders">Lihat semua →</button></div><div class="filters">${filter.controls}</div>${vehicleTable(filter.rows.slice(0,6))}<div class="table-foot"><span>Menampilkan ${Math.min(filter.rows.length,6)} dari ${filter.rows.length} kendaraan sesuai filter</span><span><button data-page="orders">Lihat detail ${icon('chevron')}</button></span></div></section><section class="panel"><div class="panel-head"><div><h2>Aktivitas Terbaru</h2><p>Jejak operasional bengkel Anda.</p></div><button data-page="audit">Semua aktivitas →</button></div>${activity()}</section></div><div class="right-column"><section class="panel"><div class="panel-head"><h2>Akses Cepat</h2></div><div class="quick-grid">${can('Super Admin','Finance')?`<button class="quick" data-action="new-visit">${icon('car')}Catat Kendaraan Masuk</button>`:`<button class="quick" data-page="orders">${icon('wrench')}Tugas Saya</button>`}<button class="quick" data-page="orders">${icon('file')}Work Order</button>${can('Super Admin','Admin Stock')?`<button class="quick" data-action="receipt">${icon('box')}Terima Sparepart</button>`:`<button class="quick" data-page="inventory">${icon('box')}Lihat Persediaan</button>`}<button class="quick" data-page="${privileged()?'finance':'inventory'}">${icon(privileged()?'wallet':'box')}${privileged()?'Catat Pembayaran':'Katalog Sparepart'}</button></div></section><section class="panel"><div class="panel-head"><h2>Perlu Perhatian</h2>${counterLink('Perlu Perhatian',low.length+state.approvals.filter(a=>a.status==='Diajukan').length,'alert-count')}</div><div class="alert-list">${low.slice(0,4).map(i=>`<div class="alert-item">${icon('alert')}<div><strong>${esc(i.name)}</strong><p>Tersisa ${i.qty} unit · Minimum ${i.minimum}</p></div></div>`).join('')||`<div class="alert-item">${icon('check')}<div><strong>Persediaan aman</strong><p>Tidak ada item di bawah stok minimum.</p></div></div>`}${state.approvals.filter(a=>a.status==='Diajukan').map(a=>`<div class="alert-item">${icon('clock')}<div><strong>Persetujuan ${esc(a.kind)}</strong><p>${num('VIS',a.source)} menunggu review.</p>${can('Super Admin')?`<button class="small" data-approve="${a.id}">Review & setujui</button>`:''}</div></div>`).join('')}</div></section><section class="panel" style="background:#e5eaf1;border-color:#d8dfe8"><div style="padding:23px"><div class="eyebrow">BENGKEL RAPI, KERJA SANTAI</div><h2 style="line-height:1.7;color:#264d83">Setiap kendaraan tercatat.<br>Setiap pekerjaan terpantau.</h2><p class="hint" style="margin-bottom:0">Pastikan QC dan pembayaran selesai sebelum menerbitkan Gate Pass OUT.</p></div></section></div></div>`}
function activity(){const map={visits:'Kendaraan masuk dicatat',login:'Pengguna masuk',Login:'Pengguna masuk',progress:'Progres pekerjaan diperbarui',items:'Master sparepart ditambahkan',receipt:'Penerimaan sparepart diposting',line:'Rincian work order ditambahkan',invoice:'Invoice diterbitkan',payment:'Pembayaran diterima',release:'Kendaraan keluar dikonfirmasi',return:'Retur sparepart dicatat',users:'Akun pengguna dibuat'};return `<div class="activity">${state.audit.slice(0,4).map(a=>`<div class="activity-item"><span class="activity-icon">${icon(map[a.action]?'check':'clock')}</span><div><strong>${esc(map[a.action]||a.action)}</strong><p>${esc(a.actor_name||'Sistem')}</p></div><time>${dt(a.created)}</time></div>`).join('')||empty('Belum ada aktivitas')}</div>`}
function vehicleTable(vs,{gateOut=false}={}){return vs.length?`<div class="table-wrap"><table><thead><tr><th>KENDARAAN / PELANGGAN</th><th>WORK ORDER</th><th>TEKNISI</th><th>STATUS</th><th>${gateOut?'AKSI':''}</th></tr></thead><tbody>${vs.map(v=>`<tr${excelRecord({'Nomor Polisi':v.plate,'Kendaraan':v.unit,'Pelanggan':v.customer,'Nomor Work Order':num('WO',v.id),'Waktu Masuk':dt(v.entered),'Teknisi':v.technician_name||'Belum ditugaskan','PIC Work Order':v.pic_technician_name||'Belum ditentukan','Status Pekerjaan':statusLabel(v.progress),'Status Kendaraan':v.exited?'Keluar':v.progress==='Selesai'?'Siap Keluar':v.progress})}><td><div class="vehicle"><span class="car-icon">${icon('car')}</span><div><strong class="plate">${esc(v.plate)}</strong><small>${esc(v.unit)} · ${esc(v.customer)}</small></div></div></td><td><strong>${num('WO',v.id)}</strong><small>${dt(v.entered)}</small></td><td>${esc(v.technician_name||'Belum ditugaskan')}<small>PIC: ${esc(v.pic_technician_name||'Belum ditentukan')}</small></td><td>${badge(v.exited?'Keluar':v.progress==='Selesai'?'Siap Keluar':v.progress)}</td><td><div class="intake-row-actions"><button class="ghost small" data-detail="${v.id}" title="Detail kunjungan">${icon('chevron')}</button>${gateOut?`<button class="small" data-completed-print-out="${v.id}" ${!v.exited?'disabled title="Konfirmasi keluar melalui detail setelah QC dan pembayaran selesai"':''}>${icon('print')} Cetak Gate Pass OUT</button>`:''}</div>${gateOut&&!v.exited?'<small>Konfirmasi keluar melalui detail terlebih dahulu.</small>':''}</td></tr>`).join('')}</tbody></table></div>`:empty('Tidak ada kendaraan yang sesuai','Ubah filter atau pencarian, atau catat kendaraan masuk.','car')}

const menuStatus={};
const progressStatuses=['Baru','Diagnosis','Menunggu Persetujuan','Di Negosiasi','Tidak Jadi','Siap Dikerjakan','Menunggu Sparepart','Dikerjakan','QC','Siap Keluar'];
function workProgressOptions(v){const e=(state.estimates||[]).find(e=>e.visit_id===v.id),status=e?.status||v.estimate_status;if(status&&status!=='Estimasi Disetujui')return [status==='Menunggu Persetujuan'?'Menunggu Persetujuan':status];return status?['Siap Dikerjakan','Diagnosis','Menunggu Sparepart','Dikerjakan','QC','Selesai']:['Baru','Diagnosis','Menunggu Persetujuan','Menunggu Sparepart','Dikerjakan','QC','Selesai']}
const visitDisplayStatus=v=>v.exited?'Keluar':v.progress==='Selesai'?'Siap Keluar':v.progress;
function statusView(key,source,getStatus,choices,initial='Semua'){
 const selected=menuStatus[key]??initial;
 const labels=['Semua',...new Set([...choices,...source.map(getStatus)])];
 const controls='<div class="master-status-filter menu-status-filter" role="group" aria-label="Filter status '+esc(key)+'"><span class="master-status-label">Status</span>'+labels.map(value=>{
  const mode=value==='Aktif'?'on':value==='Nonaktif'?'off':'';
  const label=statusLabel(value);
  const count=value==='Semua'?source.length:source.filter(row=>getStatus(row)===value).length;
  return '<button type="button" class="master-status-option '+mode+' status-'+statusTone(value)+'" data-status-menu="'+esc(key)+'" data-status-value="'+esc(value)+'" aria-pressed="'+(selected===value)+'">'+(mode?'<span class="status-switch" aria-hidden="true"></span>':'')+esc(label)+(mode==='on'?' (ON)':mode==='off'?' (OFF)':'')+' <span class="count">'+count+'</span></button>';
 }).join('')+'</div>';
 return {rows:source.filter(row=>selected==='Semua'||getStatus(row)===selected),controls};
}

function vehiclePage(){const rows=state.visits.filter(v=>(v.plate+' '+v.customer+' '+v.unit+' '+num('IN',v.id)+' '+v.complaint).toLowerCase().includes(query.toLowerCase()));return title('PENERIMAAN KENDARAAN','Pendataan Kendaraan Masuk','Catat kendaraan, pelanggan, dan keluhan saat tiba di bengkel.',can('Super Admin','Finance')?btn('Catat Kendaraan Masuk','new-visit',true):'')+'<section class="panel"><div class="filters"><input id="list-search" value="'+esc(query)+'" placeholder="Cari nomor polisi, pelanggan, atau keluhan…" aria-label="Cari kendaraan masuk"></div>'+(rows.length?'<div class="table-wrap"><table class="intake-table"><thead><tr><th>NO. PENDAFTARAN</th><th>WAKTU MASUK</th><th>KENDARAAN / PELANGGAN</th><th>KELUHAN</th><th>AKSI</th></tr></thead><tbody>'+rows.map(v=>'<tr'+excelRecord({'Nomor Pendaftaran':num('IN',v.id),'Waktu Masuk':dt(v.entered),'Nomor Polisi':v.plate,'Kendaraan':v.unit,'Pelanggan':v.customer,'Keluhan':v.complaint})+'><td>'+num('IN',v.id)+'</td><td>'+dt(v.entered)+'</td><td><strong>'+esc(v.plate)+'</strong><small>'+esc(v.unit)+'</small><small>'+esc(v.customer)+'</small></td><td>'+esc(v.complaint)+'</td><td><div class="intake-row-actions"><button class="small" data-intake-view="'+v.id+'">Lihat Data</button> <button class="small" data-intake-print="'+v.id+'">'+icon('print')+' Cetak Gate Pass IN</button>'+(!v.exited&&!v.invoice&&can('Super Admin','Finance')?' <button class="small" data-intake-edit="'+v.id+'">Edit</button>':'')+'</div></td></tr>').join('')+'</tbody></table></div>':empty('Belum ada data kendaraan masuk',query?'Tidak ada data yang cocok dengan pencarian.':'Pilih Catat Kendaraan Masuk untuk mulai mendata.','car'))+'<div class="table-foot">'+rows.length+' data kendaraan masuk</div></section>'}
function intakeDetail(id){const v=state.visits.find(v=>v.id===id);if(!v)return;open('Data Kendaraan Masuk — '+num('IN',id),'<div class="detail-top"><div><h2>'+esc(v.plate)+'</h2><p class="hint">'+esc(v.unit)+'</p></div></div><div class="detail-meta">'+[['PELANGGAN',v.customer],['TELEPON',v.phone||'—'],['WAKTU MASUK',dt(v.entered)],['KILOMETER',Number(v.km).toLocaleString('id-ID')+' km'],['PENGANTAR',v.courier||'—']].map(([label,value])=>'<div><small>'+label+'</small><strong>'+esc(value)+'</strong></div>').join('')+'</div>'+visitPlanNotice(id)+'<div class="notice"><strong>Keluhan pelanggan</strong><p>'+esc(v.complaint)+'</p><strong>Kondisi awal</strong><p>'+esc(v.condition||'—')+'</p><strong>Aksesori</strong><p>'+esc(v.accessories||'—')+'</p></div><div class="form-actions intake-detail-actions"><button id="intake-print" class="primary">'+icon('print')+' Cetak Gate Pass IN</button>'+((state.arrival_plans||[]).some(p=>p.visit_id===id)?'<button id="intake-work-order">Lihat Work Order</button>':'')+(!v.exited&&!v.invoice&&can('Super Admin','Finance')?'<button id="intake-edit">Edit Data Masuk</button>':'')+'</div>');$('#intake-print').onclick=()=>printPass(v,'IN');if($('#intake-work-order'))$('#intake-work-order').onclick=()=>detail(id);if($('#intake-edit'))$('#intake-edit').onclick=()=>newVisit(null,{},id);}
function orderPage(){const source=state.visits.filter(v=>!isCompletedWork(v)&&(v.plate+' '+v.customer+' '+v.unit+' '+num('WO',v.id)).toLowerCase().includes(query.toLowerCase())),filter=statusView('Work Order',source,visitDisplayStatus,progressStatuses.filter(s=>s!=='Selesai'));return title('PEKERJAAN BENGKEL','Work Order',can('Teknisi')?'Daftar pekerjaan yang ditugaskan kepada Anda.':'Kelola diagnosis, pekerjaan, sparepart, dan pemeriksaan akhir.')+'<section class="panel"><div class="panel-head"><h2>Antrean Pekerjaan '+counterLink('Antrean Pekerjaan',state.visits.filter(v=>!isCompletedWork(v)).length)+'</h2></div><div class="filters status-toolbar"><input id="list-search" aria-label="Cari work order" placeholder="Cari kendaraan, pelanggan, atau work order…" value="'+esc(query)+'">'+filter.controls+'</div>'+vehicleTable(filter.rows)+'<div class="table-foot">'+filter.rows.length+' pekerjaan ditampilkan</div></section>'}

function completedOrdersPage(){const completed=state.visits.filter(isCompletedWork),source=completed.filter(v=>(v.plate+' '+v.customer+' '+v.unit+' '+num('WO',v.id)+' '+(v.technician_name||'')).toLowerCase().includes(query.toLowerCase())),filter=statusView('Pekerjaan Selesai',source,v=>v.exited?'Keluar':'Siap Keluar',['Siap Keluar','Keluar']);return title('HASIL PEKERJAAN','Pekerjaan Selesai','Pekerjaan yang sudah selesai, termasuk kendaraan yang menunggu serah terima atau sudah keluar.')+'<section class="panel"><div class="panel-head"><div><h2>Pekerjaan Selesai '+counterLink('Pekerjaan Selesai',completed.length)+'</h2><p>Buka detail untuk melihat hasil pekerjaan, invoice, pembayaran, atau Gate Pass.</p></div></div><div class="filters status-toolbar"><input id="list-search" aria-label="Cari pekerjaan selesai" placeholder="Cari kendaraan, pelanggan, teknisi, atau work order…" value="'+esc(query)+'">'+filter.controls+'</div>'+(filter.rows.length?vehicleTable(filter.rows,{gateOut:true}):empty('Tidak ada pekerjaan selesai yang sesuai',completed.length?'Ubah pencarian atau filter status.':'Pekerjaan akan muncul setelah progres dinyatakan Selesai.','check'))+'<div class="table-foot">'+filter.rows.length+' dari '+completed.length+' pekerjaan selesai ditampilkan</div></section>';}

function inventoryPage(){const source=state.items.filter(i=>`${i.sku} ${i.name} ${i.category}`.toLowerCase().includes(query.toLowerCase()));const filter=statusView('Persediaan Sparepart',source,i=>i.qty<i.minimum?'Stok rendah':'Aktif',['Aktif','Stok rendah']),items=filter.rows;return title('INVENTORY MANAGEMENT','Persediaan Sparepart','Stok akurat, modal transparan, margin tetap terjaga.',can('Super Admin','Admin Stock')?btn('Penerimaan','receipt',false,'download')+btn('Tambah Item','new-item',true):'')+((state.import_batches||[]).length?btn('Arsip Impor Excel','import-archives',false,'file'):'')+`<div class="stats">${stat('Total Kode Sparepart',state.items.length,'Item aktif pada katalog bengkel','box')}${stat('Unit Tersedia',state.items.reduce((s,i)=>s+i.qty,0),'Stok fisik layak pakai','box')}${stat('Stok Kritis',state.items.filter(i=>i.qty<i.minimum).length,'Item di bawah batas minimum','alert')}${!can('Teknisi')?stat('Nilai Persediaan',rp(state.items.reduce((s,i)=>s+i.qty*i.cost,0)),'Metode rata-rata bergerak','wallet',true):stat('Kategori',new Set(state.items.map(i=>i.category)).size,'Kategori sparepart','file',true)}</div><section class="panel"><div class="filters status-toolbar"><input id="list-search" value="${esc(query)}" placeholder="Cari nama sparepart, Kode Sparepart, atau kategori…" aria-label="Cari sparepart">${filter.controls}</div>${items.length?`<div class="table-wrap"><table><thead><tr><th>SPAREPART</th><th>KATEGORI / RAK</th><th>STOK / TERSEDIA</th>${!can('Teknisi')?'<th>MODAL RATA-RATA</th><th>HARGA JUAL</th><th>MARGIN</th>':''}<th>STATUS</th>${can('Super Admin','Admin Stock')?'<th>AKSI</th>':''}</tr></thead><tbody>${items.map(i=>`<tr${excelRecord({'Nama Sparepart':i.name,'Kode Sparepart':i.sku,'Merek Sparepart':i.brand||'','Kecocokan Kendaraan':itemFitmentLabel(i),'Catatan Impor':i.import_note||'','Kategori':i.category,'Kode Rak':(state.racks||[]).find(r=>r.id===i.rack_id)?.code||'','Nama Rak':(state.racks||[]).find(r=>r.id===i.rack_id)?.name||i.rack||'','Stok':i.qty,'Satuan':i.unit||'unit','Stok Tersedia':i.available??i.qty,'Minimum Stok':i.minimum,...(!can('Teknisi')?{'Modal Rata-rata':i.cost===null?'Belum diisi':rp(i.cost),'Harga Jual':i.price===null?'Belum diisi':rp(i.price),'Margin':i.cost!==null&&i.price?((i.price-i.cost)/i.price*100).toFixed(1)+'%':'N/A','Markup':i.cost!==null&&i.price!==null&&i.cost?((i.price-i.cost)/i.cost*100).toFixed(1)+'%':'N/A'}:{}),'Status':i.qty<i.minimum?'Stok rendah':'Aktif'})}><td><strong>${esc(i.name)}</strong><small>${esc(i.sku)} · ${esc(i.brand||'—')}</small><small>${esc(itemFitmentLabel(i))}</small>${i.import_note?'<small class="import-note">'+esc(i.import_note)+'</small>':''}</td><td>${esc(i.category)}<small>Rak ${esc(inventoryMasterLabel('racks',i.rack_id,i.rack))}</small></td><td><strong>${i.qty} ${esc(i.unit||'unit')}</strong><small>Tersedia ${i.available??i.qty} · Min. ${i.minimum}</small></td>${!can('Teknisi')?`<td>${i.cost===null?'<span class="estimate-warning">Belum diisi</span>':rp(i.cost)}</td><td>${i.price===null?'<span class="estimate-warning">Belum diisi</span>':rp(i.price)}</td><td>${i.cost!==null&&i.price?((i.price-i.cost)/i.price*100).toFixed(1)+'%':'N/A'}<small>Markup ${i.cost!==null&&i.price!==null&&i.cost?((i.price-i.cost)/i.cost*100).toFixed(1)+'%':'N/A'}</small></td>`:''}<td>${badge(i.qty<i.minimum?'Stok rendah':'Aktif')}</td>${can('Super Admin','Admin Stock')?`<td>${i.import_id&&(i.cost===null||i.price===null)?'<button class="small action-attention" data-import-values="'+i.id+'">Lengkapi Harga</button> ':''}<button class="small" data-edit-item="${i.id}">Edit</button> <button class="small" data-fitment="${i.id}">Relasi Kendaraan</button> <button class="small" data-item-approval="${i.id}">Harga / Opname</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('Tidak ada sparepart yang sesuai','Ubah filter status atau kata pencarian.')}</section>${!can('Teknisi')?`<section class="panel"><div class="panel-head"><h2>Riwayat Mutasi Stok</h2></div>${state.movements.length?`<div class="table-wrap"><table><thead><tr><th>WAKTU</th><th>ITEM</th><th>JENIS</th><th>JUMLAH</th><th>MODAL / UNIT</th><th>REFERENSI</th></tr></thead><tbody>${state.movements.slice(0,30).map(m=>`<tr><td>${dt(m.created)}</td><td>${esc(m.item_name)}</td><td>${esc(m.type)}</td><td>${m.qty>0?'+':''}${m.qty}</td><td>${m.cost===null?'Belum diisi':rp(m.cost)}</td><td>${esc(m.source)}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada mutasi')}</section>`:''}`}
function paymentStatus(paid,total){return paid>=total&&paid>0?'Lunas':paid>0?'DP':'Belum dibayar'}
function customerBillingPanel(estimateId,invoiceId=null){const bill=(state.estimate_billing||[]).find(b=>b.estimate_id===estimateId),v=invoiceId?state.visits.find(v=>v.invoice===invoiceId):null,total=v?.total??bill?.total,paid=v?.paid??bill?.paid;if(total===undefined)return '';invoiceId=invoiceId||bill?.invoice;const payments=(state.payments||[]).filter(p=>invoiceId?p.invoice===invoiceId:p.estimate_id===estimateId),cashback=(state.cashbacks||[]).filter(c=>payments.some(p=>p.id===c.payment_id)).reduce((sum,c)=>sum+c.amount,0);return '<section class="customer-billing"><h3>Pembayaran Pelanggan</h3><p class="hint">'+(invoiceId?num('INV',invoiceId)+' · ':'')+(estimateId?num('EST',estimateId):'Tagihan Work Order')+'</p><div class="amount-row"><span>Status pembayaran</span>'+badge(paymentStatus(paid,total))+'</div><div class="amount-row"><span>Nilai tagihan'+(!invoiceId?' disetujui':'')+'</span><strong>'+rp(total)+'</strong></div><div class="amount-row"><span>DP / pembayaran diterima</span><strong>'+rp(paid)+'</strong></div><div class="amount-row"><span>Sisa pembayaran</span><strong>'+rp(total-paid)+'</strong></div>'+(!invoiceId?'<p class="hint">Pembayaran sebelum invoice dicatat sebagai uang muka dan otomatis diperhitungkan saat invoice akhir terbit setelah QC.</p>':'')+(paid<total&&can('Super Admin','Finance')&&(invoiceId||bill?.status==='Estimasi Disetujui'&&bill.current!==false)?'<button class="primary" '+(invoiceId?'data-payment-invoice="'+invoiceId+'"':'data-payment-estimate="'+estimateId+'"')+'>Catat Pembayaran / DP</button>':'')+(payments.length?'<div class="payment-history">'+payments.map(p=>'<div class="amount-row"><span>'+esc(p.payment_kind||'Pembayaran')+' · '+dt(p.created)+'<small>'+esc(p.method)+' · '+esc(p.reference||'—')+'</small></span><strong>'+rp(p.amount)+'</strong></div>').join('')+'</div>':'')+(privileged()?'<p class="notice"><strong>Cashback internal: '+rp(cashback)+'</strong><br>Cashback dicatat sebagai pengeluaran terpisah dan tidak ditampilkan pada invoice pelanggan.</p>':'')+'</section>';}
function approvedPaymentsPanel(){const rows=(state.estimate_billing||[]).filter(b=>b.status==='Estimasi Disetujui'&&!b.invoice&&b.current!==false);return '<section class="panel"><div class="panel-head"><div><h2>DP & Pembayaran Estimasi Disetujui</h2><p>Terima DP atau lunas langsung sebelum invoice akhir terbit.</p></div></div>'+(rows.length?'<div class="table-wrap"><table><thead><tr><th>ESTIMASI / PELANGGAN</th><th>TAGIHAN DISETUJUI</th><th>DIBAYAR</th><th>SISA</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody>'+rows.map(b=>'<tr'+excelRecord({'Nomor Estimasi':num('EST',b.estimate_id),'Pelanggan':b.customer,'Nomor Polisi':b.plate,'Tagihan Disetujui':rp(b.total),'Dibayar':rp(b.paid),'Sisa':rp(b.remaining),'Status Pembayaran':b.payment_status})+'><td><strong>'+num('EST',b.estimate_id)+'</strong><small>'+esc(b.customer)+' · '+esc(b.plate)+'</small></td><td>'+rp(b.total)+'</td><td>'+rp(b.paid)+'</td><td>'+rp(b.remaining)+'</td><td>'+badge(b.payment_status)+'</td><td>'+(can('Super Admin','Finance')&&b.remaining>0?'<button class="small" data-payment-estimate="'+b.estimate_id+'">Catat Pembayaran / DP</button>':'—')+'</td></tr>').join('')+'</tbody></table></div>':empty('Tidak ada estimasi menunggu invoice','Estimasi disetujui yang belum berinvoice akan muncul di sini.','wallet'))+'</section>';}
function bindCustomerPayments(root){root.querySelectorAll('[data-payment-estimate],[data-payment-invoice]').forEach(button=>button.onclick=()=>paymentForm(Number(button.dataset.paymentEstimate)||null,Number(button.dataset.paymentInvoice)||null));}
function paymentForm(estimateId=null,invoiceId=null){const bill=(state.estimate_billing||[]).find(b=>b.estimate_id===estimateId),v=invoiceId?state.visits.find(v=>v.invoice===invoiceId):null,total=v?.total??bill?.total,paid=v?.paid??bill?.paid,remaining=total-paid;if(!(remaining>0))return toast('Tagihan sudah lunas.');const visitId=v?.id??bill?.visit_id,kinds=paid?['DP','Pelunasan']:['DP','Lunas Langsung'],allowed=kinds.filter(k=>k!=='DP'||remaining>1),request_id=crypto.randomUUID?.()||'PAY-'+Date.now()+'-'+Math.random().toString(36).slice(2);form('Catat Pembayaran Pelanggan',select('Jenis pembayaran','payment_kind',options(allowed.map(k=>[k,k])),true)+field('Jumlah pembayaran (Rp)','amount','number',{min:1,full:true})+select('Metode pembayaran','method',options([['Tunai','Tunai'],['Transfer','Transfer bank']]))+field('Referensi pembayaran','reference','text',{required:false})+'<p class="notice full">Sisa tagihan '+rp(remaining)+'. DP dapat dicatat beberapa kali; pilih pelunasan untuk membayar seluruh sisanya.</p><details class="full payment-cashback"><summary>Cashback internal (tidak tampil di invoice)</summary><div class="form-grid">'+field('Cashback (Rp)','cashback_amount','number',{min:0,value:0,required:false,full:true})+field('Catatan cashback internal','cashback_note','text',{required:false,full:true})+'</div></details>','payment',{...(invoiceId?{invoice:invoiceId}:{estimate_id:estimateId}),request_id},'Posting Pembayaran',()=>{if(page==='estimates'&&estimateId)showEstimate(estimateId);else if(visitId)detail(visitId)});const kind=$('#modal-form [name=payment_kind]'),amount=$('#modal-form [name=amount]'),cashback=$('#modal-form [name=cashback_amount]'),note=$('#modal-form [name=cashback_note]');const sync=()=>{const dp=kind.value==='DP';amount.readOnly=!dp;amount.value=dp?'':rupiahDisplay(remaining);amount.max=dp?remaining-1:remaining;updateFormGuide($('#modal-form'))};kind.onchange=sync;cashback.oninput=()=>{note.required=Number(moneyValue(cashback))>0;updateFormGuide($('#modal-form'))};sync();}
function financePage(){const invoices=state.visits.filter(v=>v.invoice),total=invoices.reduce((s,v)=>s+v.total,0),paid=state.payments.reduce((s,p)=>s+p.amount,0);const filter=statusView('Invoice',invoices.filter(v=>(num('INV',v.invoice)+' '+v.customer+' '+v.plate).toLowerCase().includes(query.toLowerCase())),v=>paymentStatus(v.paid,v.total),['Belum dibayar','DP','Lunas']);return title('FINANCE','Invoice & Pembayaran','Tagihan, pembayaran parsial, dan arus kas dalam satu tempat.',can('Super Admin','Finance')?btn('Pengeluaran Kas','expense',true,'wallet'):'')+`<div class="stats">${stat('Penjualan Terposting',rp(total),'Total invoice diterbitkan','file')}${stat('Pembayaran Diterima',rp(paid),'Tunai dan transfer','wallet',true)}${stat('Piutang Pelanggan',rp(invoices.reduce((sum,v)=>sum+v.total-v.paid,0)),'Saldo invoice belum lunas','clock')}${stat('Invoice Aktif',invoices.filter(v=>v.total>v.paid).length,'Menunggu pembayaran','file')}</div>${approvedPaymentsPanel()}<section class="panel"><div class="panel-head"><h2>Daftar Invoice</h2></div><div class="filters status-toolbar"><input id="list-search" aria-label="Cari invoice" placeholder="Cari invoice, pelanggan, atau kendaraan…" value="${esc(query)}">${filter.controls}</div>${filter.rows.length?`<div class="table-wrap"><table><thead><tr><th>INVOICE / PELANGGAN</th><th>KENDARAAN</th><th>TOTAL</th><th>TERBAYAR</th><th>SISA</th><th>STATUS</th><th></th></tr></thead><tbody>${filter.rows.map(v=>`<tr${excelRecord({'Nomor Invoice':num('INV',v.invoice),'Pelanggan':v.customer,'Nomor Polisi':v.plate,'Total':rp(v.total),'Terbayar':rp(v.paid),'Sisa':rp(v.total-v.paid),'Status Pembayaran':paymentStatus(v.paid,v.total)})}><td><strong>${num('INV',v.invoice)}</strong><small>${esc(v.customer)}</small></td><td>${esc(v.plate)}</td><td>${rp(v.total)}</td><td>${rp(v.paid)}</td><td>${rp(v.total-v.paid)}</td><td>${badge(paymentStatus(v.paid,v.total))}</td><td><button class="small" data-detail="${v.id}">Detail</button></td></tr>`).join('')}</tbody></table></div>`:empty('Tidak ada invoice yang sesuai','Ubah filter status atau kata pencarian.','file')}</section><section class="panel"><div class="panel-head"><h2>Buku Penerimaan Kas / Bank</h2></div>${state.payments.length?`<div class="table-wrap"><table><thead><tr><th>WAKTU</th><th>INVOICE</th><th>METODE</th><th>REFERENSI</th><th>JUMLAH</th></tr></thead><tbody>${state.payments.map(p=>`<tr${excelRecord({'Waktu':dt(p.created),'Nomor Invoice':p.invoice?num('INV',p.invoice):'','Nomor Estimasi':!p.invoice?num('EST',p.estimate_id):'','Jenis Pembayaran':p.payment_kind||'Pembayaran','Metode':p.method,'Referensi':p.reference||'','Jumlah':rp(p.amount)})}><td>${dt(p.created)}</td><td>${p.invoice?num('INV',p.invoice):num('EST',p.estimate_id)}<small>${esc(p.payment_kind||'Pembayaran')}</small></td><td>${esc(p.method)}</td><td>${esc(p.reference||'—')}</td><td><strong>${rp(p.amount)}</strong></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada pembayaran',undefined,'wallet')}</section>${supplierPanels()}`}
function supplierPanels(){const source=state.movements.filter(m=>m.type==='Penerimaan'),balanceOf=m=>Math.round(m.qty*m.cost)-state.supplier_payments.filter(p=>p.movement===m.id).reduce((s,p)=>s+p.amount,0),filter=statusView('Hutang Supplier',source,m=>balanceOf(m)>0?'Belum lunas':'Lunas',['Lunas','Belum lunas']);return `<section class="panel"><div class="panel-head"><h2>Hutang Supplier / Penerimaan</h2></div><div class="filters">${filter.controls}</div>${filter.rows.length?`<div class="table-wrap"><table><thead><tr><th>REFERENSI</th><th>ITEM</th><th>TOTAL</th><th>SISA HUTANG</th><th></th></tr></thead><tbody>${filter.rows.map(m=>{const paid=state.supplier_payments.filter(p=>p.movement===m.id).reduce((s,p)=>s+p.amount,0),balance=Math.round(m.qty*m.cost)-paid;return `<tr><td>${esc(m.source)}</td><td>${esc(m.item_name)}</td><td>${rp(m.qty*m.cost)}</td><td>${rp(balance)}</td><td>${balance&&can('Super Admin','Finance')?`<button class="small" data-supplier-pay="${m.id}" data-balance="${balance}">Bayar</button>`:badge('Lunas')}</td></tr>`}).join('')}</tbody></table></div>`:empty('Belum ada hutang supplier')}</section><section class="panel"><div class="panel-head"><h2>Pengeluaran Kas / Bank</h2></div>${state.expenses.length?`<div class="table-wrap"><table><thead><tr><th>WAKTU</th><th>KATEGORI / PENERIMA</th><th>REFERENSI</th><th>METODE</th><th>JUMLAH</th></tr></thead><tbody>${state.expenses.map(e=>`<tr${excelRecord({'Waktu':dt(e.created),'Kategori':e.category,'Penerima':e.recipient,'Referensi':e.reference,'Metode':e.method,'Jumlah':rp(e.amount)})}><td>${dt(e.created)}</td><td><strong>${esc(e.category)}</strong><small>${esc(e.recipient)}</small></td><td>${esc(e.reference)}</td><td>${esc(e.method)}</td><td>${rp(e.amount)}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada pengeluaran kas')}</section>`}
function manualJournal(){open('Jurnal Penyesuaian',`<form id="journal-form"><div id="journal-error"></div><div class="form-grid">${field('Keterangan jurnal','memo','text',{full:true})}${field('Akun debit','debitAccount')}${field('Akun kredit','creditAccount')}${field('Jumlah (Rp)','amount','number',{min:1,full:true})}</div><div class="form-actions"><button class="primary">Posting Jurnal</button></div></form>`);$('#journal-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));try{await api('manual-journal',{memo:b.memo,entries:[{account:b.debitAccount,debit:Number(b.amount)},{account:b.creditAccount,credit:Number(b.amount)}]});closeModal();await load();toast('Jurnal diposting')}catch(e){$('#journal-error').innerHTML=`<div class="error">${esc(e.message)}</div>`}}}
function accountingPage(){const periodFilter=statusView('Periode',state.periods,p=>p.closed?'Terkunci':'Terbuka',['Terkunci','Terbuka']);return title('ACCOUNTING','Jurnal & Tutup Periode','Posting otomatis yang seimbang dan terhubung ke dokumen sumber.',can('Akuntan')?btn('Jurnal Manual','manual-journal',false,'plus')+btn('Buka Periode','reopen',false,'refresh')+btn('Tutup Periode','period',true,'shield'):'')+`<div class="notice">Jurnal terbentuk otomatis dari penerimaan, pemakaian, retur, invoice, dan pembayaran. Dokumen terposting tidak dapat diedit. Periode terkunci: ${state.periods.filter(p=>p.closed).map(p=>esc(p.month)).join(', ')||'Belum ada'}.</div><section class="panel"><div class="panel-head"><h2>Status Periode</h2></div><div class="filters">${periodFilter.controls}</div>${periodFilter.rows.length?'<div class="table-wrap"><table><thead><tr><th>PERIODE</th><th>STATUS</th></tr></thead><tbody>'+periodFilter.rows.map(p=>'<tr><td>'+esc(p.month)+'</td><td>'+badge(p.closed?'Terkunci':'Terbuka')+'</td></tr>').join('')+'</tbody></table></div>':empty('Tidak ada periode tercatat yang sesuai','Periode yang belum pernah ditutup masih terbuka.')}</section><section class="panel"><div class="panel-head"><h2>Jurnal Transaksi</h2><span class="badge green">Double-entry</span></div>${state.journals.length?`<div class="table-wrap"><table><thead><tr><th>SUMBER / TANGGAL</th><th>KETERANGAN / AKUN</th><th>DEBIT</th><th>KREDIT</th></tr></thead><tbody>${state.journals.map(j=>JSON.parse(j.entries).map((e,i)=>`<tr${excelRecord({'Sumber':j.source,'Tanggal':dt(j.created),'Keterangan':j.memo,'Akun':e.account,'Debit':rp(e.debit||0),'Kredit':rp(e.credit||0)})}><td>${i===0?`<strong>${esc(j.source)}</strong><small>${dt(j.created)}</small>`:''}</td><td>${i===0?`<strong>${esc(j.memo)}</strong><br>`:''}${esc(e.account)}</td><td>${e.debit?rp(e.debit):'—'}</td><td>${e.credit?rp(e.credit):'—'}</td></tr>`).join('')).join('')}</tbody></table></div>`:empty('Belum ada jurnal','Jurnal akan terbentuk saat transaksi diposting.','file')}</section>`}
function reportPage(){const inv=state.visits.filter(v=>v.invoice),revenue=inv.reduce((s,v)=>s+v.total,0),cost=state.lines.filter(l=>l.item&&inv.some(v=>v.id===l.visit)).reduce((s,l)=>s+Math.round((l.qty-l.returned)*l.cost),0),stock=state.items.reduce((s,i)=>s+i.qty*i.cost,0);const accounts={};state.journals.forEach(j=>JSON.parse(j.entries).forEach(e=>{accounts[e.account]??={debit:0,credit:0};accounts[e.account].debit+=e.debit||0;accounts[e.account].credit+=e.credit||0}));return title('BUSINESS INSIGHTS','Laporan Bengkel','Ringkasan penjualan, margin sparepart, dan posisi persediaan.',btn('Ekspor CSV','export',false,'download'))+`<div class="stats">${stat('Nilai Persediaan',rp(stock),'Modal rata-rata × stok fisik','box',true)}${privileged()?stat('Penjualan',rp(revenue),'Invoice terposting','chart')+stat('HPP Sparepart',rp(cost),'Modal snapshot transaksi','box')+stat('Laba Kotor',rp(revenue-cost),'Termasuk jasa, sebelum beban','wallet'):stat('Total Item',state.items.length,'Kode Sparepart tercatat','box')+stat('Stok Kritis',state.items.filter(i=>i.qty<i.minimum).length,'Perlu pengadaan','alert')+stat('Total Mutasi',state.movements.length,'Pergerakan persediaan','refresh')}</div><div class="report-grid"><section class="panel"><div class="panel-head"><h2>Margin Sparepart Terjual</h2></div>${state.lines.filter(l=>l.item&&inv.some(v=>v.id===l.visit)).length?`<div class="table-wrap"><table><thead><tr><th>ITEM</th><th>NETO</th><th>HPP</th><th>MARGIN</th></tr></thead><tbody>${state.lines.filter(l=>l.item&&inv.some(v=>v.id===l.visit)).map(l=>`<tr><td>${esc(l.description)}</td><td>${rp((l.qty-l.returned)*l.price)}</td><td>${rp((l.qty-l.returned)*l.cost)}</td><td>${l.price?((l.price-l.cost)/l.price*100).toFixed(2)+'%':'N/A'}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada penjualan sparepart')}</section><section class="panel"><div class="panel-head"><h2>${privileged()?'Neraca Saldo':'Nilai Persediaan per Item'}</h2></div>${privileged()?Object.keys(accounts).length?`<div class="table-wrap"><table><thead><tr><th>AKUN</th><th>DEBIT</th><th>KREDIT</th></tr></thead><tbody>${Object.entries(accounts).map(([a,b])=>`<tr><td>${esc(a)}</td><td>${rp(Math.max(0,b.debit-b.credit))}</td><td>${rp(Math.max(0,b.credit-b.debit))}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada saldo akun'):state.items.map(i=>`<div class="amount-row" style="padding:15px 20px"><span>${esc(i.name)}</span><strong>${i.qty>0&&i.cost===null?'Belum diisi':rp(i.qty*i.cost)}</strong></div>`).join('')||empty('Belum ada persediaan')}</section></div>`}
function userPage(){const source=state.users.filter(u=>(u.name+' '+u.email+' '+u.role).toLowerCase().includes(query.toLowerCase())),filter=statusView('Akun Pengguna',source,u=>u.active?'Aktif':'Nonaktif',['Aktif','Nonaktif']);return title('ACCESS MANAGEMENT','Akun & Hak Akses','Akun terpisah untuk setiap petugas. Penonaktifan mempertahankan jejak transaksi.',btn('Tambah Pengguna','new-user',true,'users'))+`<section class="panel"><div class="panel-head"><h2>Pengguna Bengkel</h2><span class="count">${state.users.length} akun</span></div><div class="filters status-toolbar"><input id="list-search" aria-label="Cari akun" placeholder="Cari nama, email, atau peran…" value="${esc(query)}">${filter.controls}</div><div class="table-wrap"><table><thead><tr><th>PENGGUNA</th><th>PERAN</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody>${filter.rows.map(u=>`<tr${excelRecord({'Nama Pengguna':u.name,'Email':u.email,'Peran':u.role,'Izin Gate Pass':u.role==='Finance'?(u.gatepass?'Diizinkan':'Tidak diizinkan'):'','Status':u.active?'Aktif':'Nonaktif'})}><td><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></td><td>${esc(u.role)}${u.role==='Finance'?`<small>Gate Pass: ${u.gatepass?'Diizinkan':'Tidak diizinkan'}</small>`:''}</td><td>${badge(u.active?'Aktif':'Nonaktif')}</td><td>${u.id!==state.user.id?`${u.role==='Finance'?`<button class="small" data-gate-permission="${u.id}" data-enabled="${u.gatepass?0:1}">${u.gatepass?'Cabut':'Beri'} Izin Gate Pass</button> `:''}<button class="small" data-reset-user="${u.id}">Reset akses</button> <button class="small" data-toggle-user="${u.id}">${u.active?'Nonaktifkan':'Aktifkan'}</button>`:'Akun Anda'}</td></tr>`).join('')}</tbody></table></div>${!filter.rows.length?empty('Tidak ada akun yang sesuai','Ubah filter status atau kata pencarian.'):''}</section><div class="notice">Teknisi hanya mendapat kunjungan yang ditugaskan, tanpa akses modal dan margin. Admin mengelola simulasi estimasi dan keputusan pelanggan; Admin Stock mengelola stok; Finance mengelola kendaraan, invoice dan pembayaran; Akuntan mengelola jurnal dan periode.</div>`}
