 modal.querySelectorAll('[data-cancel-reservation]').forEach(el=>el.onclick=()=>confirmAction('Batalkan Reservasi','Stok tersedia akan dilepaskan.','cancel-reservation',{id:Number(el.dataset.cancelReservation)},()=>detail(id)));
 $('#print-in').onclick=()=>printPass(v,'IN');if($('#print-out'))$('#print-out').onclick=()=>printPass(v,'OUT');
 if($('#progress'))$('#progress').onclick=()=>form('Perbarui Progres',select('Status pekerjaan','progress',options(workProgressOptions(v).map(s=>[s,statusLabel(s)])),true)+`<p class="hint full">Status persetujuan mengikuti estimasi terbaru yang terkait dengan kunjungan ini. Pilih Selesai hanya setelah pemeriksaan QC lulus. Jika QC gagal, kembalikan ke Dikerjakan.</p>`,'progress',{id},'Simpan Progres',()=>detail(id));
