function updateEstimateSummary(){
 let valid=true;const requested=new Map();for(const l of estimateDraft.lines)if(l.kind==='part'&&l.item_id)requested.set(Number(l.item_id),(requested.get(Number(l.item_id))||0)+Number(l.qty||0));
 for(const l of estimateDraft.lines){const info=$('#estimate-lines [data-line-info="'+l.key+'"]');if(!info)continue;const lineTotal=Number(l.qty)*Number(l.price);let content='<strong>Subtotal baris: '+rp(Number.isFinite(lineTotal)?Math.round(lineTotal):0)+'</strong>';
  if(l.kind==='part'&&l.manual){if(!String(l.description||'').trim())valid=false;content+='<span class="hint">Sparepart manual · belum tercatat di inventory. Harga diisi untuk estimasi ini; ketersediaan perlu dikonfirmasi.</span>'}
  else if(l.kind==='part'){const item=state.items.find(i=>i.id===Number(l.item_id));if(!item){valid=false;content+='<span class="hint">Pilih sparepart dari inventory.</span>'}else{const compatible=estimateItems().some(i=>i.id===item.id);if(!compatible){valid=false;content+='<span class="estimate-warning">Sparepart tidak cocok untuk kendaraan yang dipilih. Pilih ulang.</span>'}const available=quoteAvailable(item),shortage=Math.max(0,Math.round((requested.get(item.id)-available)*1000)/1000);content+='<span class="'+(shortage?'estimate-warning':'hint')+'">Stok tersedia '+available+' · kebutuhan '+requested.get(item.id)+(shortage?' · kurang '+shortage:' · mencukupi')+'</span>';if(item.fitment_mode==='unverified')content+='<span class="hint">Kecocokan tipe belum dipetakan.</span>';if(Number(l.price)!==item.price)content+='<span class="estimate-warning">Harga snapshot '+rp(l.price)+'; harga inventory kini '+rp(item.price)+'. Gunakan Perbarui Harga bila diperlukan.</span>'}}
  else {if(!String(l.description||'').trim())valid=false;if(l.service_id){const service=(state.service_catalog||[]).find(s=>s.id===Number(l.service_id));content+='<span class="hint">Harga standar acuan '+rp(l.standard_price)+' / '+esc(l.service_unit||'pekerjaan')+'</span>';if(Number(l.price)!==Number(l.standard_price))content+='<span class="estimate-warning">Harga disesuaikan untuk estimasi ini; harga katalog tidak berubah.</span>';if(service&&service.price!==Number(l.standard_price))content+='<span class="hint">Harga katalog terkini '+rp(service.price)+'. Gunakan tombol harga standar untuk memuatnya.</span>';if(!service?.active)content+='<span class="hint">Jasa katalog nonaktif. Rincian tersimpan tetap dipertahankan.</span>'}}info.innerHTML=content;
 }
 try{const result=calculateEstimate(estimatePayload());$('#estimate-summary').innerHTML='<div class="estimate-totals"><div class="amount-row"><span>Biaya jasa</span><strong>'+rp(result.services)+'</strong></div><div class="amount-row"><span>Biaya sparepart</span><strong>'+rp(result.parts)+'</strong></div><div class="amount-row"><span>Subtotal</span><strong>'+rp(result.subtotal)+'</strong></div><div class="amount-row"><span>Diskon</span><strong>− '+rp(result.discount_amount)+'</strong></div><div class="amount-row"><span>Dasar pajak setelah diskon</span><strong>'+rp(result.tax_base)+'</strong></div><div class="amount-row"><span>Pajak '+result.tax_rate+'%</span><strong>'+rp(result.tax_amount)+'</strong></div><div class="amount-row total"><span>Total estimasi</span><strong>'+rp(result.total)+'</strong></div></div>'}catch(e){valid=false;$('#estimate-summary').innerHTML='<div class="error">'+esc(e.message)+'</div>'}
 $('#estimate-save').disabled=!valid||!estimateDraft.vehicle_id;updateFormGuide($('#estimate-form'));
}
